        {id:"mlc-g3",prompt:"إذا كان لخطوتين 2 و3 اختيارات، فما عدد النواتج؟",options:["5","6","8","9"],answer:1,explanation:"باستخدام مبدأ الضرب: 2×3 = 6."}
